import{_ as r}from"./chunks/defdd2f4680f96492ad6.Mu3dm5Mc.js";import{_ as l,C as o,o as p,c as i,j as t,a as s,E as n,a6 as h}from"./chunks/framework.CnPv4DE1.js";const q=JSON.parse('{"title":"如果你感到迷茫——去理解人生的这3个阶段","description":"","frontmatter":{"title":"如果你感到迷茫——去理解人生的这3个阶段","originalTitle":"If You Feel Lost — Understand These 3 Phases Of Life","date":"2022-05-02","originalUrl":"https://thedankoe.com/letters/if-you-feel-lost-understand-these-3-phases-of-life/","minutes":7,"sourceHash":"c2d974bebe5f829bd3e22a2d4e8e833ce291ae870c4c30f102d25ee49b6169e6","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/if-you-feel-lost-understand-these-3-phases-of-life/"}]]},"headers":[],"relativePath":"letters/if-you-feel-lost-understand-these-3-phases-of-life.md","filePath":"letters/if-you-feel-lost-understand-these-3-phases-of-life.md"}'),d={name:"letters/if-you-feel-lost-understand-these-3-phases-of-life.md"};function f(c,e,u,m,b,_){const a=o("ArticleMeta");return p(),i("div",null,[e[0]||(e[0]=t("h1",{id:"如果你感到迷茫——去理解人生的这3个阶段",tabindex:"-1"},[s("如果你感到迷茫——去理解人生的这3个阶段 "),t("a",{class:"header-anchor",href:"#如果你感到迷茫——去理解人生的这3个阶段","aria-label":'Permalink to "如果你感到迷茫——去理解人生的这3个阶段"'},"​")],-1)),n(a),e[1]||(e[1]=h('<p><a href="https://www.youtube.com/embed/X47wVjXWW4M?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><a href="https://open.spotify.com/embed/episode/2MaWDuIu1vAoNqqqm9f5Yv?si=0a769b7296ac4020&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我总觉得我的人生是分阶段展开的。在某一个阶段，我感到迷茫。在另一个阶段，我被钉在书桌前。充满能量。深度沉浸在心流（flow）状态中。构建我的未来。在又一个阶段，我只是按部就班地走个过场，但乐在其中。</p><p>愚蠢的是，我在高中或大学时从未有过这种感觉。那时候老师和雇主引导着我的注意力。自主生活的周期性只有在我必须管理自己的目标时才会发挥作用。只有当我必须掌握自己的注意力，以决定我想在生活中去往何方时，它才会出现。</p><p>迷茫的阶段最具破坏性，却也最有启发性。在黑暗中摸索，希望能找到一根蜡烛。找到了一根。眼睁睁看着它熄灭。又找到另一根，并希望在黑暗再次崩塌前，它能指引你找到下一根。</p><p>通过觉察和渴望改善的意图，这些周期的破坏性已经降低了。</p><p>我只能想象其他一些人的感受。不知道如何对那些感到迷茫的时期加杠杆（leverage）——而事实上，你只是在为下一轮的高温做准备。</p><p>就像蒸桑拿。不要抗拒它。<em>让它净化你。</em></p><h2 id="进步的3个驱动力" tabindex="-1">进步的3个驱动力 <a class="header-anchor" href="#进步的3个驱动力" aria-label="Permalink to &quot;进步的3个驱动力&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>进步的3个驱动力</p><p>当你致力于根据自己的目标——而不是别人的目标——去构建生活时，会有3个进步的驱动力。这意味着如果你参与其中——或者意识到了——这些阶段，你就在向更美好的生活迈进。</p><p>这些阶段会发生在每个人身上，但对于那些没有做自己喜欢的事情的人来说是最具毁灭性的。对于那些追随别人设定的道路而不是开辟自己道路的人来说也是如此。他们从童年起就被规训去迎接一个不断重复的未来。</p><p>理解这些阶段将帮助你认清自己在旅途中的位置，你能做些什么，以及如何做出准确的决定。</p><p><strong>进步的3个驱动力是：</strong></p><ol><li>强度（Intensity）</li><li>持续性（Consistency）</li><li>好奇心（Curiosity）</li></ol><p>它们以周期的形式出现。阶段性的。一个阶段引出另一个阶段。它们是生命中不可避免的周期。潮起潮落。无为（Wu wei）。推与拉。秘密在于放手。顺其自然地让这些周期发生。顺流而下。抗拒它只会让你被困在人生的那个阶段，直到你学会它试图教给你的功课。</p><p>强度用于构建。持续性用于维护。好奇心用于探索。</p><p>这些不仅是生命的周期，也是年、月、周和日的周期。在本文中，我们将深入探讨宏观视角。与此同时，你能否开始在日常生活中觉察到这些周期？</p><p><em>以下是你该如何驾驭它们：</em></p><h3 id="探索未知" tabindex="-1">探索未知 <a class="header-anchor" href="#探索未知" aria-label="Permalink to &quot;探索未知&quot;">​</a></h3><blockquote><p>“当你走到你所拥有的所有光芒的边缘，迈出进入未知黑暗的第一步时，你必须相信两件事之一会发生。要么会有坚实的东西让你立足，要么你会被教会如何飞翔。” —— 帕特里克·奥弗顿（Patrick Overton）</p></blockquote><p>我们将从好奇心阶段开始，因为很多人对它存在误解。这就是人们终其一生被困住的阶段。有无限的改进空间，<em>却与他们舒适区的边缘保持着50英尺的距离。</em></p><p><strong>生活是一系列的实验。</strong> 没有人——没有一个灵魂——曾经或将要弄清楚这一切。未知是一片充满无限机遇的土地。然而，大多数人把它看作是一片充满巨大风险的土地。</p><p>附带说明：与所有其他事物一样，风险只是一个标签。一个暗示着回报的捏造概念。1%的顶尖表现者看清了风险的本质，<em>它是生活的一部分</em>。99%的表现平庸者只看到风险带来的结果，它摧毁了他们熟悉的泡沫。<em>真可怕</em>。</p><p>好奇心阶段很棘手。它看起来不像是在探索。它感觉像是你在太空中漂浮。没有可以让你脚踏实地的惯例。在生活中没有方向感。卡在“我想余生都做这个！”和“谁会余生都做这个啊？”的中间状态。</p><p>我们必须采取探险家的心态。在丛林中披荆斩棘，寻找能改变人生的新发现。探索未知是“把屎*糊在墙上，看看什么能粘住（不断试错）”的真实世界体现。</p><p>轻松驾驭这个阶段需要直觉、臣服和接受——但也有更有效的方法来驾驭它。试试这个：</p><ul><li>写下你的20个兴趣爱好</li><li>记下相关的兴趣（交叉点）</li><li>让自己沉浸在与这些相关的资讯中</li><li>阅读书籍，听播客，关注该领域的意见领袖</li><li>将这些点连接起来，并理解现实世界中的实用价值</li><li>把你学到的东西教给别人，以更好地理解它</li></ul><p>在这一切结束时，你会对你必须前进的方向有更深的理解。你的神经生物学——兴奋的感觉——会暗示你的激情所在。在未知的旅途中进行自我教育。教育将觉察之光照亮未知的地图。把你的时间投资在免费内容上。<a href="https://join.modernmastery.co/" target="_blank" rel="noreferrer">把你的金钱投资在你渴望成为的人的教导上</a>（课程或辅导）。</p><p>好奇心阶段用于探索、实验和做出新发现。那些新发现会引领你走上一条你想走的道路——而不是别人想让你走的道路。这需要你与你的直觉——你的神经生物学——保持联系，并让好奇心成为你的内在驱动力。这是测试新兴趣、评估其效用并最终将这些点连接起来的时候。这会带来巨大的清晰感，将你推入下一个阶段。</p><h3 id="快速构建更好的未来" tabindex="-1">快速构建更好的未来 <a class="header-anchor" href="#快速构建更好的未来" aria-label="Permalink to &quot;快速构建更好的未来&quot;">​</a></h3><p>强度阶段用于构建与你的好奇心相关的项目。当清晰感袭来时——早中晚的界限变得模糊，你只想挤出时间尽快把事情做完。没有什么能阻止你开辟自己的道路。专注是无缝衔接的。心流似乎会持续一整天。你甚至不需要你那宝贝的待办事项App来让你保持正轨。</p><p>这个阶段在好奇心阶段之后。它发生在一切豁然开朗时。你做出了新发现，爆发出清晰感，并制定出一套将你推向新高度的策略。你已经能<em>感觉</em>到自己置身于未来的状态中。你是谁以及你想成为谁融为一体。你就是那个人。你只是在等待时间追赶上来。</p><blockquote><p>强度带来清晰。它不仅创造了动力，还创造了你感受到摩擦或满足感所需的压力。 —— 马库斯·白金汉（Marcus Buckingham）</p></blockquote><p>构建阶段是为了将好奇心转化为痴迷。它是为了酿造那杯将你送入心流状态的神经化学鸡尾酒。它是为了在朝着自主和精通的方向构建时，培养激情和目标。这是你构建未来的地方。个人自由。自我实现（self-actualization）。这个阶段最好用在具有高潜在盈利能力的项目上。它可以从一个爱好开始——也可以一直是一个爱好——但如果你想在这条路上走下去，自主权是必不可少的。</p><p>在这个阶段的末尾，如果你想维持你的进步，你就必须将一切系统化。</p><h3 id="持续性带来复利" tabindex="-1">持续性带来复利 <a class="header-anchor" href="#持续性带来复利" aria-label="Permalink to &quot;持续性带来复利&quot;">​</a></h3><p>在强度阶段结束时，你会达到一个新的基准线。不管是心理上的、身体上的、精神上的，还是财务上的。如果你不维持这个基准线，你就会跌入新的低谷。再说一次，这是一个周期。你不必非得退回到好奇心阶段，只为再次感到迷茫。</p><p>持续性最好通过系统来驾驭。这些系统应该围绕基本面展开。那些能带来增长、具有杠杆效应的行动。把这些基本面融入你的日常惯例中，如果可以的话将它们自动化，并把讨厌做的事情外包出去。</p><p>再次，拿出纸和笔，或者下载我的计划表：</p><ul><li>记下你那些具备杠杆效应、以目标为导向的任务</li><li>安排时间块来执行它们</li><li>避免分心，进入深度工作（deep work）的惯例</li><li>在精力最充沛的时候做这些事</li><li>经常复盘，并将你不喜欢的事情委派给技术工具或虚拟助理（VA）</li></ul><p>通过构建适当的生活和业务系统，你可以通过每天2-4小时的专注工作来维持全职收入。无代码技术的发展减少了一人企业主（solopreneurs）的工作量。数字产品和服务的创作者（creators）拥有一种许多人无法想象的奢侈。你只能通过自动化或委派任务来减少工作时间。员工才是那个被委派任务的人。</p><p>一旦你感到稳定，你就可以维持你的进步，并一头扎进另一个好奇心阶段。探索未知，通过自我教育找到自己的路，让新发现将你推入强度周期。（如果你能在已经建立的基础上继续构建，那是加分项——这就是杠杆[leverage]。）</p><h3 id="宏观与微观阶段" tabindex="-1">宏观与微观阶段 <a class="header-anchor" href="#宏观与微观阶段" aria-label="Permalink to &quot;宏观与微观阶段&quot;">​</a></h3><p>一旦你有意识地体验过这些阶段，它们就会变得更具可预测性。你就能更高效地驾驭它们。你可以预测将会发生什么，并减轻对未来的担忧。</p><p>问题在于，<em>这些阶段不仅存在于宏观中。</em>它们也存在于微观中。你可以利用对这些阶段的理解来打造一个可持续的日常惯例。例如，我：</p><ul><li>在早晨的前2个小时进行构建（强度）</li><li>在接下来的2个小时进行维护（持续性）</li><li>在下午进行探索（好奇心）</li></ul><p><a href="https://thedankoe.com/the-3-habit-morning-routine-to-end-procrastination/" target="_blank" rel="noreferrer">这已经融入了我的日程安排中。</a> 一种精心设计的生活方式。宏观阶段中包含着微观阶段。这是划分时间与知道何时转换方向之间的一种平衡。</p><p>但我们可以以后再聊这个。我们会在后续的文章中深入探讨生活方式设计。</p><p>如果你想每周获取我文章的最新动态，以及我本周精选的3条生活与商业建议，<a href="https://links.thedankoe.com/#letter" target="_blank" rel="noreferrer">订阅The Koe Letter</a>。</p><hr><p><a href="/en/letters/if-you-feel-lost-understand-these-3-phases-of-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',53))])}const P=l(d,[["render",f]]);export{q as __pageData,P as default};
